#!/usr/bin/env bash
# P1 one matrix cell: restart the new stack (+ADRF) at the period already generated by
# `PERIOD=<s> newstack.sh gen && newstack.sh deploy`, verify 46/46 UEs, start 5 pps ping on all
# 46 UEs, tcpdump on 5GC (EES HTTP :8080, ADRF :9888, consumer :9095, PFCP :8805), subscribe the
# group subset for <nue> UEs, and snapshot CPU (/proc/<pid>/stat) and MongoDB sizes at the start
# and end of a 600 s window. Raw data -> cost/raw/<tag>.{pcap.gz,meta.json}.
# usage: p1_cell.sh <period_s> <nue: 6|26|46> <tag>
set -u
P=$1; NUE=$2; TAG=$3
R=$HOME/Research-data-collection; S=$R/scripts/testbed.sh; N=$R/scripts/newstack.sh
INFRA=$HOME/free5gc-NWDAF/5G_Infrastructure; RAW=$R/cost/raw; mkdir -p "$RAW"
vssh() { (cd "$INFRA/$1" && vagrant ssh -c "$2" 2>/dev/null); }
DUR=600; W=$(( P >= 30 ? 90 : 60 ))
avail=$(df --output=avail -BG ~ | tail -1 | tr -dc 0-9); echo "[$TAG] disk avail ${avail}G"
[ "$avail" -lt 8 ] && { echo "STOP: disk < 8 GB (rule 8)"; exit 2; }

# --- clean restart (fresh subscriptions per cell)
$S stop-consumer >/dev/null; $S stop-ran >/dev/null
for v in gNB gNB2; do vssh $v 'pkill -x ping; true'; done
$N stop-nwdaf >/dev/null; $N stop-adrf >/dev/null; $N stop-core >/dev/null; $N stop-upf >/dev/null; sleep 2
$N start-upf; $N start-core; $N start-adrf; sleep 2; $N start-nwdaf; $S start-ran; sleep 30
for attempt in 1 2; do
  V=$(python3 "$R/scripts/p0_verify_ues.py" --out "$RAW/$TAG.ue_check.csv"); echo "$V" | tail -2
  echo "$V" | grep -q "new UEs: 40  #1 pass 40  #2 pass 40" && echo "$V" | grep -q "existing UEs: 6  #1 pass 6  #2 pass 6" && break
  [ $attempt = 2 ] && { echo "STOP: #1/#2 not 46/46 after RAN restart"; exit 3; }
  echo "UE check failed, restarting RAN once"; $S stop-ran; $S start-ran; sleep 30
done
$S start-ping $(( W + DUR + 60 )) >/dev/null

# --- capture, then subscribe
vssh 5GC "mkdir -p ~/p1cap && rm -f ~/p1cap/*; (sudo setsid nohup tcpdump -i any -s 0 -U -w ~/p1cap/$TAG.pcap 'tcp port 8080 or tcp port 9888 or tcp port 9095 or udp port 8805' > ~/p1cap/tcpdump.log 2>&1 < /dev/null &); sleep 2; pgrep -x tcpdump >/dev/null && echo tcpdump running"
S0=$(date -u +%s); SINCE=$(date -u -d @$S0 +%FT%TZ)
CONSUMER=consumer-p1-$NUE.json $S start-consumer >/dev/null; echo "[$TAG] subscribed at/after $SINCE ($NUE UEs, period $P s)"
START=$(date -u -d @$(( S0 + W )) +%FT%TZ); END=$(date -u -d @$(( S0 + W + DUR )) +%FT%TZ)

snap() {  # $1 = label
  local f="$RAW/$TAG.snap-$1.txt"
  vssh 5GC 'echo "5GC t=$(date +%s.%N) tck=$(getconf CLK_TCK) nproc=$(nproc)"; for p in smf nwdaf adrf amf; do pid=$(pgrep -x $p | head -1); echo "5GC $p $(awk "{print \$14+\$15}" /proc/$pid/stat)"; done' > "$f"
  for v in UPF-EES UPF-EES2; do vssh $v 'echo "$(hostname) t=$(date +%s.%N) tck=$(getconf CLK_TCK) nproc=$(nproc)"; echo "$(hostname) upf $(sudo awk "{print \$14+\$15}" /proc/$(pgrep -x upf | head -1)/stat)"' >> "$f"; done
  mongosh --quiet mongodb://127.0.0.1/free5gc --eval 'const a=db.getSiblingDB("adrf"); const f=db.stats(), d=a.stats(), r=a.data_store_records.stats(); print("mongo t="+Date.now()/1000, "free5gc.dataSize="+f.dataSize, "free5gc.storageSize="+f.storageSize, "adrf.dataSize="+d.dataSize, "adrf.storageSize="+d.storageSize, "adrf.records="+r.count, "adrf.records.size="+r.size)' >> "$f"
}
waitto() { while [ "$(date -u +%s)" -lt "$(date -u -d "$1" +%s)" ]; do sleep 2; done; }
waitto "$START"; snap start
waitto "$END"; snap end
sleep 5
vssh 5GC 'sudo pkill -INT -x tcpdump; sleep 2; cat ~/p1cap/tcpdump.log | tail -3'
CONSUMER=consumer-p1-$NUE.json $S stop-consumer >/dev/null

# --- per-UE completeness in the window (stop the matrix if a UE / UPF stalled)
CHK=$(mongosh --quiet mongodb://127.0.0.1/free5gc --eval "const r=db['nwdaf.upfTrafficData'].aggregate([{\$match:{timestamp:{\$gte:new Date('$START'),\$lt:new Date('$END')}}},{\$group:{_id:'\$metadata.correlationId',n:{\$sum:1}}}]).toArray(); const ns=r.map(x=>x.n); print(r.length, ns.length?Math.min(...ns):0, ns.length?Math.max(...ns):0, ns.reduce((a,b)=>a+b,0))")
read nc nmin nmax ntot <<< "$CHK"; EXP=$(( DUR / P ))
echo "[$TAG] window $START..$END records: corrIds=$nc min=$nmin max=$nmax total=$ntot expected/UE=$EXP"
ADRFN=$(mongosh --quiet mongodb://127.0.0.1/adrf --eval "print(db.data_store_records.countDocuments({ingestedAt:{\$gte:new Date('$START'),\$lt:new Date('$END')}}))")

# --- fetch the pcap (gzip in the VM, verify sha256 on both sides)
vssh 5GC "gzip -1 -f ~/p1cap/$TAG.pcap && sha256sum ~/p1cap/$TAG.pcap.gz | cut -c1-64" > "$RAW/$TAG.sha.vm"
(cd "$INFRA/5GC" && vagrant ssh -c "cat ~/p1cap/$TAG.pcap.gz" 2>/dev/null) > "$RAW/$TAG.pcap.gz"
if [ "$(sha256sum "$RAW/$TAG.pcap.gz" | cut -c1-64)" = "$(tr -dc 0-9a-f < "$RAW/$TAG.sha.vm")" ]; then
  echo "[$TAG] pcap ok $(du -h "$RAW/$TAG.pcap.gz" | cut -f1)"; vssh 5GC "rm -f ~/p1cap/$TAG.pcap.gz"; rm -f "$RAW/$TAG.sha.vm"
else echo "STOP: pcap sha mismatch for $TAG (left in 5GC ~/p1cap)"; exit 4; fi

python3 - "$RAW/$TAG.meta.json" <<EOF
import json, sys
json.dump(dict(tag="$TAG", period=$P, nue=$NUE, since="$SINCE", start="$START", end="$END", duration=$DUR,
               records=dict(corrIds=int("$nc" or 0), min=int("$nmin" or 0), max=int("$nmax" or 0), total=int("$ntot" or 0), expected_per_ue=$EXP),
               adrf_records_in_window=int("$ADRFN" or 0)), open(sys.argv[1], "w"), indent=1)
EOF
if [ "${nc:-0}" -ne "$NUE" ] || [ "${nmin:-0}" -lt $(( EXP * 9 / 10 )) ]; then echo "STOP: [$TAG] incomplete collection (corrIds $nc/$NUE, min $nmin < 90% of $EXP)"; exit 5; fi
echo "CELL-DONE $TAG"
